+#[test]
+fn hashline_count_salt_rejects_a_stale_duplicate_and_the_retry_lands() {
+    // Duplicate copies of `return None`; a block holding another copy is added
+    // above between turns, exactly as tall as the gap. Under salt = "count"
+    // every copy's hash changes, so the stale anchor is refused and the retry
+    // with the fresh anchor lands on the final copy.
+    let env = Env::new(
+        "hashline-count",
+        json!({ "steps": [
+            { "call": "read", "args": { "path": "access.py" } },
+            { "call": "shell", "args": { "command": "sed -i '2i\\    if u.admin:\\n        return None' access.py" } },
+            { "call": "edit", "args": { "path": "access.py", "edits": [ { "op": "set", "anchor": "5:gg", "text": "    return user.id" } ] } },
+            { "call": "edit", "args": { "path": "access.py", "edits": [ { "op": "set", "anchor": "7:yf", "text": "    return user.id" } ] } },
+            { "text": "done" }
+        ] }),
+    );
+    env.config("[tools]\neditor = \"hashline\"\n\n[tools.hashline]\nsalt = \"count\"\n");
+    std::fs::write(
+        env.work.join("access.py"),
+        "def f(u):\n    if u.banned:\n        return None\n    audit(u)\n    return None\n",
+    )
+    .unwrap();
+    let out = env.run(&["run", "--json", "--no-learn", "change the final return"]);
+    assert!(out.status.success(), "{}", text(&out));
+    let reqs = env.requests();
+    assert_eq!(
+        last_tool_result(&reqs[1]),
+        "1:ep|def f(u):\n2:zq|    if u.banned:\n3:pl|        return None\n4:sz|    audit(u)\n5:gg|    return None\n"
+    );
+    let rejected = last_tool_result(&reqs[3]);
+    assert!(rejected.starts_with("Error: REJECTED: 1 of 1 edit(s)"), "{rejected}");
+    assert!(rejected.contains("ANCHOR_MISMATCH") && rejected.contains("5:nz|        return None"), "{rejected}");
+    let applied = last_tool_result(&reqs[4]);
+    assert!(applied.starts_with("ok: applied 1 edit(s) to access.py: replaced line 7"), "{applied}");
+    assert!(
+        applied.lines().any(|l| l.starts_with("7:") && l.ends_with("|    return user.id")),
+        "fresh anchors: {applied}"
+    );
+    assert_eq!(
+        std::fs::read_to_string(env.work.join("access.py")).unwrap(),
+        "def f(u):\n    if u.admin:\n        return None\n    if u.banned:\n        return None\n    audit(u)\n    return user.id\n"
+    );
+    let events: Vec<Value> =
+        String::from_utf8_lossy(&out.stdout).lines().filter_map(|l| serde_json::from_str(l).ok()).collect();
+    let edits: Vec<&Value> = events.iter().filter(|e| e["event"] == "tool_end" && e["name"] == "edit").collect();
+    assert_eq!((edits[0]["ok"].clone(), edits[0]["code"].clone()), (json!(false), json!("ANCHOR_MISMATCH")));
+    assert_eq!((edits[1]["ok"].clone(), edits[1]["data"]["status"].clone()), (json!(true), json!("applied")));
+    let manifest = events.iter().find(|e| e["event"] == "manifest").expect("manifest event");
+    assert_eq!(manifest["hashline"]["salt"], "count");
+}
